// JS Date has no fold concept: the only way to land on either occurrence
// is to already know the UTC instant. Walking UTC minutes shows local time
// repeating 01:xx twice with no local-only way to tell which pass you're on.
const dtf = new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', hour12: false, hour: '2-digit', minute: '2-digit' });
for (const h of [4, 5, 6]) {
  const utcMs = Date.UTC(2024, 10, 3, h, 30, 0);
  console.log(h + ':30 UTC ->', dtf.format(new Date(utcMs)));
}
